<?php
/** Real dbDelta/InnoDB upgrade from schema44 and authenticated REST. All mail/HTTP is intercepted. */
declare(strict_types=1);
if(PHP_SAPI!=='cli')exit;$bootstrap=getenv('EDERP_TEST_BOOTSTRAP');if(!$bootstrap||!is_file($bootstrap))exit(2);$_SERVER['HTTP_HOST']='erp-test.local';$_SERVER['REQUEST_URI']='/';require $bootstrap;
if(!defined('EDERP_TEST_DATABASE')||EDERP_TEST_DATABASE!==true||defined('EDERP_SQLITE_TEST'))throw new RuntimeException('Exige WordPress/MySQL descartável autorizado.');
require_once dirname(__DIR__).'/autoload.php';require __DIR__.'/wordpress-migration-fixtures.php';require __DIR__.'/fixtures/scholarships.php';require_once ABSPATH.'wp-admin/includes/user.php';
use EducacionalERP\Application\{Scholarships,ScholarshipCatalog,Operations,CatalogService,AcademicService,FinanceService,ExportService,RenewalService,StudentWorkflow,Coligadas};
use EducacionalERP\Infrastructure\Database\{Database,Installer};
use EducacionalERP\Infrastructure\WordPress\{Access,SchemaMigration};
use EducacionalERP\Presentation\Rest\Controller;
use EducacionalERP\Domain\{Money,FinancialStatus};
$admin=get_users(['role'=>'administrator','number'=>1])[0];wp_set_current_user($admin->ID);Access::install();$oldPrefix=$wpdb->prefix;$saved=[];$users=[];$checks=0;$http=0;$mail=0;
foreach(['ederp_schema_version','ederp_schema_error','ederp_schema_integrity','ederp_schema_attempt_release','ederp_pontualidade'] as $name)$saved[$name]=get_option($name,null);
add_filter('pre_http_request',static function()use(&$http){$http++;return new WP_Error('test_http_blocked','Transporte bloqueado no teste.');},999,3);
add_filter('pre_wp_mail',static function()use(&$mail){$mail++;return true;},999,2);
function okWS(bool $condition,string $label):void {global $checks;if(!$condition)throw new RuntimeException($label);$checks++;echo "PASS: $label\n";}
function requestWS(string $route,?array $data=null,string $key=''):WP_REST_Response {$r=new WP_REST_Request($data===null?'GET':'POST','/erp-educacional/v1/'.$route);if($data!==null){$r->set_header('Content-Type','application/json');$r->set_header('Idempotency-Key',$key?:bin2hex(random_bytes(16)));$r->set_body(wp_json_encode($data));}return rest_do_request($r);}
function titlesWS(Database $db,int $id):array{return $db->rows('SELECT l.*,p.numero FROM '.$db->table('lancamentos').' l JOIN '.$db->table('parcelas').' p ON p.idparcela=l.idparcela WHERE p.idcontrato=%d ORDER BY p.numero',[$id]);}
try{
    $wpdb->prefix='bs_'.bin2hex(random_bytes(5)).'_';$legacy=json_decode(file_get_contents(__DIR__.'/fixtures/schema-44.json'),true,512,JSON_THROW_ON_ERROR);$db=fixtureM($legacy);
    $wpdb->update($db->table('contratos'),['quantidade_parcelas'=>2,'valor_original_total'=>'2000.00','valor_liquido_total'=>'2000.00'],['idcontrato'=>1]);$due=(new DateTimeImmutable())->modify('+1 month')->format('Y-m-d');
    $wpdb->insert($db->table('parcelas'),['idparcela'=>2,'idcontrato'=>1,'numero'=>2,'competencia'=>substr($due,0,7).'-01','vencimento_original'=>$due,'valor_original'=>'1000.00','valor_liquido'=>'1000.00','regra_desconto_condicional'=>'{}','regra_encargos'=>'{}']);
    $wpdb->insert($db->table('lancamentos'),['idlancamento'=>2,'idparcela'=>2,'codpessoa_rf_original'=>2,'codpessoa_rf_atual'=>2,'descricao'=>'PARCELA ABERTA DO BACKUP','emissao'=>'2026-01-05','vencimento'=>$due,'valor_original'=>'1000.00','valor_liquido'=>'1000.00','saldo_aberto'=>'1000.00']);
    $before=snapshotM($db,$legacy);update_option('ederp_schema_version','44');delete_option('ederp_schema_error');update_option('ederp_pontualidade','103.00');SchemaMigration::run($db);
    okWS(get_option('ederp_schema_version')===Installer::VERSION&&!get_option('ederp_schema_error'),'dbDelta e InnoDB concluem a migração 44 → 45');okWS(snapshotM($db,$legacy)===$before,'migração preserva todos os campos históricos, pagamentos, contratos e termos');okWS($db->get('lancamentos',2)['pontualidade_snapshot']===null&&$db->get('contratos',1)['mensalidade_base_total']===null,'registros antigos permanecem na regra anterior até concessão explícita');
    $catalog=new ScholarshipCatalog($db);okWS(count($catalog->listing()['items'])===2,'migração cadastra Integral e 50%');SchemaMigration::run($db);okWS(snapshotM($db,$legacy)===$before&&count($catalog->listing()['items'])===2,'repetir migração não altera valores nem duplica bolsas padrão');
    $ops=new Operations($db);$access=new Access($db);$academic=new AcademicService($db,$ops);$cat=new CatalogService($db,$ops);rest_get_server();(new Controller($db,$access,$academic,$cat,new FinanceService($db,$ops),new ExportService($db),new RenewalService($db,$ops,$academic,$access),new StudentWorkflow($db,$ops,$cat,$academic)))->register();
    $staff=wp_insert_user(['user_login'=>'bolsa_staff_'.bin2hex(random_bytes(5)),'user_pass'=>wp_generate_password(40),'role'=>'erp_secretaria']);$users[]=$staff;
    foreach([0,$staff] as $actor){wp_set_current_user($actor);foreach(['bolsas'=>null,'integracao/bolsas'=>null,'contratos/1/bolsas'=>null,'bolsas-concedidas/1/editar'=>['versao'=>1],'bolsas-concedidas/1/retirar'=>['versao'=>1]] as $route=>$data)okWS(in_array(requestWS($route,$data)->get_status(),[401,403],true),'REST bloqueia usuário sem administração em '.$route);okWS(in_array(requestWS('bolsas',['nome'=>'invasão'])->get_status(),[401,403],true)&&in_array(requestWS('contratos/1/bolsas',['idbolsa'=>1])->get_status(),[401,403],true),'REST bloqueia criação de catálogo e concessão sem administração');}
    wp_set_current_user($admin->ID);$half=array_values(array_filter($catalog->listing()['items'],fn($r)=>$r['codigo_padrao']==='cinquenta'))[0];$paid=$db->get('lancamentos',1);$key=bin2hex(random_bytes(16));$data=scholarshipSelection($half,1,2);$response=requestWS('contratos/1/bolsas',$data,$key);okWS($response->get_status()===200&&$response->get_data()['parcelas_alteradas']===1&&$response->get_data()['parcelas_preservadas']===1,'REST recalcula somente a parcela sem baixa do backup');$changed=$db->get('lancamentos',2);okWS($changed['valor_original']==='1103.00'&&$changed['valor_liquido']==='603.00'&&FinancialStatus::present($changed)['saldo_a_pagar']==='500.00'&&$db->get('parcelas',2)['valor_liquido']==='603.00','DECIMAL nativo persiste 1103, bolsa 500 e pontualidade 103 em parcela e lançamento');okWS($db->get('lancamentos',1)===$paid,'baixa parcial do backup permanece byte a byte intacta');$snapshot=serialize([$db->rows('SELECT * FROM '.$db->table('lancamentos')),$db->rows('SELECT * FROM '.$db->table('contrato_bolsas'))]);okWS(requestWS('contratos/1/bolsas',$data,$key)->get_data()===$response->get_data()&&$snapshot===serialize([$db->rows('SELECT * FROM '.$db->table('lancamentos')),$db->rows('SELECT * FROM '.$db->table('contrato_bolsas'))]),'mesma chave retorna concessão confirmada sem recalcular ou duplicar');
    $fixture=seedScholarships($db);$full=createScholarshipContract($db,$fixture,'NATIVO-INTEGRAL',[scholarshipSelection($fixture['full'])]);$titles=titlesWS($db,(int)$full['idcontrato']);okWS(count($titles)===12&&array_unique(array_column($titles,'valor_liquido'))===['0.00']&&$db->get('matriculas',(int)$full['idmatricula'])['status']==='cursando','matrícula integral real aceita zero e libera Cursando sem baixa fictícia');okWS(!$db->row('SELECT idbaixa FROM '.$db->table('baixas').' WHERE idlancamento=%d',[(int)$titles[0]['idlancamento']]),'isenção integral não insere pagamento no InnoDB');
    $both=createScholarshipContract($db,$fixture,'NATIVO-SESSENTA',[scholarshipSelection($fixture['half']),scholarshipSelection($fixture['ten'])]);$bothTitle=titlesWS($db,(int)$both['idcontrato'])[0];okWS($bothTitle['valor_liquido']==='503.00'&&FinancialStatus::present($bothTitle)['saldo_a_pagar']==='400.00','duas bolsas somam 60% na matrícula nativa');
    $beforeFailure=serialize([$db->rows('SELECT * FROM '.$db->table('contrato_bolsas')),$db->rows('SELECT * FROM '.$db->table('parcelas')),$db->rows('SELECT * FROM '.$db->table('lancamentos')),$db->rows('SELECT * FROM '.$db->table('auditoria'))]);$invalid=requestWS('contratos/'.$both['idcontrato'].'/bolsas',scholarshipSelection($fixture['full']));okWS($invalid->get_status()===422&&$beforeFailure===serialize([$db->rows('SELECT * FROM '.$db->table('contrato_bolsas')),$db->rows('SELECT * FROM '.$db->table('parcelas')),$db->rows('SELECT * FROM '.$db->table('lancamentos')),$db->rows('SELECT * FROM '.$db->table('auditoria'))]),'transação InnoDB reverte concessão, valores e auditoria acima de 100%');
    $company=$db->insert('coligadas',['nome'=>'OUTRO COLÉGIO','razao_social'=>'OUTRO COLÉGIO']);Coligadas::within($company,function()use($catalog,$db,$half){$catalog->seed(Coligadas::current());okWS(count($catalog->listing()['items'])===2,'cada coligada recebe seu próprio catálogo padrão');okWS(requestWS('contratos/1/bolsas')->get_status()===422,'contrato de outra coligada não pode ser consultado');$fresh=$catalog->listing()['items'][0];okWS(requestWS('contratos/1/bolsas',scholarshipSelection($fresh,1,2))->get_status()===422,'concessão não atravessa a coligada do contrato');});
    update_option('ederp_schema_error','migração pendente de teste');okWS(requestWS('bolsas')->get_status()===503,'migração incompleta bloqueia novos cadastros e recálculos');delete_option('ederp_schema_error');okWS($http===0&&$mail===0,'testes não enviam cobranças ou e-mails externos');
    $pending=createScholarshipContract($db,$fixture,'NATIVO-EDITAR-PENDENTE',[scholarshipSelection($fixture['half'])],true);$pendingId=(int)$pending['idcontrato'];$edit=requestWS('contratos/'.$pendingId,['versao'=>$db->get('contratos',$pendingId)['versao'],'mensalidade_base_total'=>'13200.00','desconto_base_total'=>'120.00','motivo'=>'Correção da base pendente']);okWS($edit->get_status()===200&&$edit->get_data()['valor_liquido_total']==='7716.00','REST corrige base de contrato pendente e reprojeta bolsas em DECIMAL');$academic->generateInstallments($pendingId,bin2hex(random_bytes(16)));okWS(titlesWS($db,$pendingId)[0]['valor_liquido']==='643.00','geração nativa posterior usa a base corrigida sem duplicar bolsas');
    echo "WORDPRESS_SCHOLARSHIPS_OK: $checks verificações / WordPress $wp_version / MariaDB ".$wpdb->db_version()."\n";
}finally{wp_set_current_user($admin->ID);foreach($users as $id)if(is_int($id))wp_delete_user($id);$wpdb->prefix=$oldPrefix;foreach($saved as $name=>$value){if($value===null)delete_option($name);else update_option($name,$value,false);}}
